style:
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
:root{color-scheme:light;--bg:#fff;--fg:#14161a;--dim:#6b7280;--ac:#c2410c;--bar:#f4f5f7;--ln:#e3e5e9;--ok:#15803d}
html[data-t=dark]{color-scheme:dark;--bg:#0e1012;--fg:#e9ecef;--dim:#8b939c;--ac:#ff9147;--bar:#181b1f;--ln:#282d33;--ok:#4ade80}
html,body{margin:0;background:var(--bg);color:var(--fg);
 font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;overscroll-behavior:none}
#bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:9;display:flex;align-items:center;gap:8px;
 padding:7px 10px;background:var(--bar);border-bottom:1px solid var(--ln)}
button{font:inherit;font-weight:700;color:var(--fg);background:var(--bg);border:1px solid var(--ln);
 border-radius:9px;padding:9px 12px;min-width:44px;min-height:44px;font-size:15px}
button:active{background:var(--ln)}
#now{flex:1;min-width:0;font-weight:700;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#now i{font-style:normal;color:var(--ac);font-weight:800;margin-left:8px}
#set{padding:8px 10px 40px}
#set h1{font-size:26px;margin:12px 4px 2px}
#set p{margin:0 4px 14px;color:var(--dim);font-size:14px}
ul{list-style:none;margin:0;padding:0}
#set li.ult{box-shadow:inset 4px 0 0 var(--ac);background:var(--bar)}
li a{display:flex;align-items:center;gap:12px;padding:15px 8px;border-bottom:1px solid var(--ln);
 text-decoration:none;color:var(--fg)}
.n{color:var(--dim);font-size:14px;min-width:26px;text-align:right}
.t{flex:1;font-weight:700;font-size:18px}
.k{color:var(--ac);font-weight:700;font-size:15px}
/* touch-action:none => o navegador nunca rola nem cancela o ponteiro aqui;
   o tap sempre chega e a rolagem manual e feita no JS */
section{padding:6px 8px 75vh;touch-action:none}
h2{font-size:21px;margin:8px 2px 2px}
h2 em{display:block;font-style:normal;font-size:15px;color:var(--ac);font-weight:700;margin-top:2px}
pre{margin:14px 0 0;font-family:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
 line-height:1.42;white-space:pre;overflow-x:auto}
pre b{color:var(--ac);font-weight:700}
#nav{position:fixed;left:0;right:0;bottom:0;z-index:9;display:none;align-items:center;gap:7px;
 padding:8px 10px calc(env(safe-area-inset-bottom) + 8px);background:var(--bar);border-top:1px solid var(--ln)}
#nav button{flex:1}
#b-topo{font-size:13px;letter-spacing:.04em}
/* play marcado de verde: contorno verde parado, verde cheio rolando */
#b-play{color:var(--ok);border:2px solid var(--ok)}
#b-play.on{background:var(--ok);border-color:var(--ok);color:#fff}
#vel{min-width:56px;text-align:center;font-weight:700;font-size:14px;color:var(--dim)}
.ic{display:inline-block;width:17px;height:17px;border-radius:50%;border:2px solid currentColor;
 background:linear-gradient(90deg,currentColor 50%,transparent 50%);vertical-align:-3px}
html[data-t=dark] .ic{background:linear-gradient(90deg,transparent 50%,currentColor 50%)}
#b-set{visibility:hidden}
#b-play{visibility:hidden;padding:9px 14px}
#flash{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:20;
 font-size:64px;line-height:1;color:var(--ac);opacity:0;pointer-events:none}
#flash.on{animation:fl .55s ease-out}
#flash.sm{font-size:30px;font-weight:800}
@keyframes fl{0%{opacity:.85;transform:translate(-50%,-50%) scale(.85)}
 100%{opacity:0;transform:translate(-50%,-50%) scale(1.25)}}
body.aberto #b-play{visibility:visible}
body.aberto #b-set{visibility:visible}
/* A-/A+ e o pedal so onde servem */
body:not(.aberto) #b-menos,body:not(.aberto) #b-mais{display:none}
body.aberto #b-ped{display:none}
#b-ped{padding:9px 10px;font-size:13px;min-width:46px}
/* transpose */
#b-tom{padding:9px 9px;font-size:13px;min-width:48px}
#b-tom.on{color:var(--ac);border-color:var(--ac)}
body:not(.aberto) #b-tom{display:none}
#tp{position:fixed;right:10px;top:calc(env(safe-area-inset-top,0px) + 64px);z-index:12;display:none;
 align-items:center;gap:8px;padding:10px;border:1px solid var(--ln);border-radius:14px;background:var(--bar);
 box-shadow:0 8px 28px rgba(0,0,0,.28)}
#tp.on{display:flex}
#tp button{min-width:52px;font-size:17px}
#tp #tp-0{font-size:13px;min-width:0}
#tp-v{min-width:84px;text-align:center;font-weight:800;font-size:20px;line-height:1.1}
#tp-v small{display:block;font-size:12px;font-weight:700;color:var(--dim)}
#pedal{position:fixed;inset:0;z-index:40;display:none;flex-direction:column;gap:13px;
 padding:calc(env(safe-area-inset-top) + 16px) 16px calc(env(safe-area-inset-bottom) + 16px);
 background:var(--bg);overflow-y:auto}
#pedal h3{margin:0;font-size:21px}
#pedal p{margin:0;color:var(--dim);font-size:14px;line-height:1.45}
#pedal p b{color:var(--fg)}
.pl{display:flex;align-items:center;gap:10px;border:1px solid var(--ln);border-radius:12px;padding:10px 12px}
.pl .lb{flex:1;font-weight:700;font-size:16px}
.pl .vl{font-size:13px;color:var(--ac);font-weight:700;
 font-family:ui-monospace,Menlo,monospace;text-align:right;max-width:44%}
.pl.ouvindo{outline:2px solid var(--ac);outline-offset:-2px}
#psig{font-family:ui-monospace,Menlo,monospace;font-size:13px;color:var(--dim);
 border:1px dashed var(--ln);border-radius:10px;padding:11px;min-height:44px}
#pmidi{font-size:13px;color:var(--dim);line-height:1.4}
#pbt{display:flex;gap:8px;flex-wrap:wrap}
#pbt button{flex:1;min-width:120px;font-size:14px}
.vs{display:inline-block;flex:none;margin:0 auto 0 9px;padding:2px 6px 1px;border:1.5px solid var(--ac);border-radius:5px;
 color:var(--ac);font-size:11px;font-weight:800;letter-spacing:.08em;line-height:1.3}
li a .t:has(+ .vs){flex:0 1 auto;min-width:0}
#now .vs{margin:0 0 0 8px;vertical-align:2px;font-size:10px}
:root{--rm:#c8341f}
html[data-t=dark]{--rm:#ff6e5c}
#capa{padding:12px 16px 48px}
#capa h1{font-size:28px;margin:12px 0 2px}
#capa>p{margin:0 0 18px;color:var(--dim);font-size:14px}
#cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr));gap:14px;max-width:860px}
.card{position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;gap:2px;
 aspect-ratio:1/1;max-width:100%;min-height:0;padding:20px 22px;text-align:left;border:1px solid var(--ln);
 border-radius:18px;background:var(--bar);color:var(--fg);cursor:pointer}
.card:active{background:var(--ln)}
.card:focus-visible{outline:3px solid var(--ac);outline-offset:2px}
.card .tag{position:absolute;top:18px;left:22px;font-size:12px;font-weight:800;letter-spacing:.12em;color:var(--dim)}
.card.prox{border:2px solid var(--ac)}
.card.prox .tag{color:var(--ac)}
.card.passou{opacity:.7}
.card .dia{font-size:13px;font-weight:800;letter-spacing:.14em;color:var(--dim)}
.card .dt{font-size:clamp(56px,14vw,96px);font-weight:800;line-height:.95;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.card .loc{font-size:20px;font-weight:700;color:var(--ac);min-height:1.2em}
.card .qt{margin-top:10px;font-size:14px;font-weight:600;color:var(--dim)}
#b-capa{display:none}
body.indice:not(.aberto) #b-capa{display:inline-block}
body.indice:not(.aberto) #b-set{display:none}
body.capa #b-ed{display:none}
li.sec{display:flex;align-items:center;padding:16px 8px 6px;font-weight:800;font-size:13px;
 letter-spacing:.08em;color:var(--ac);border-bottom:2px solid var(--ac)}
li.sec .t{flex:1;font-weight:800;font-size:13px}
li.off{display:flex;align-items:center;gap:12px;padding:15px 8px;border-bottom:1px solid var(--ln);opacity:.5}
li.off .t{flex:1;font-weight:700;font-size:18px}
li.off .k{font-size:12px;color:var(--dim);font-weight:600}
.gr,.rm{display:none}
#b-ed.on{background:var(--ac);border-color:var(--ac);color:#fff}
body.aberto #b-ed{display:none}
body.edit li{display:flex;align-items:center;border-bottom:1px solid var(--ln)}
body.edit li.sec{border-bottom:2px solid var(--ac)}
body.edit li>a{flex:1;border-bottom:none;pointer-events:none}
body.edit .rm{display:flex;align-items:center;justify-content:center;flex:0 0 44px;width:44px;height:44px;
 min-width:44px;padding:0;margin-left:6px;color:var(--rm);font-size:17px;font-weight:800}
body.edit .gr{display:block;position:relative;flex:0 0 48px;width:48px;height:48px;
 margin-left:6px;border:1px solid var(--ln);border-radius:10px;background:var(--bg);touch-action:none;cursor:grab}
body.edit .gr:active{background:var(--ln);cursor:grabbing}
.gr::before,.gr::after{content:'';position:absolute;top:50%;margin-top:-2px;width:4px;height:4px;border-radius:50%;
 background:var(--dim);box-shadow:0 -10px 0 var(--dim),0 10px 0 var(--dim)}
.gr::before{left:16px}
.gr::after{left:28px}
body.arrastando{user-select:none;-webkit-user-select:none}
li.drag{pointer-events:none;background:var(--bar);border-radius:10px;
 box-shadow:0 8px 22px rgba(0,0,0,.45);outline:2px solid var(--ac);outline-offset:-2px}
body.edit #set{padding-bottom:170px}
#edbar{position:fixed;left:0;right:0;bottom:0;z-index:10;display:none;align-items:center;gap:7px;
 padding:8px 10px calc(env(safe-area-inset-bottom) + 8px);background:var(--bar);border-top:2px solid var(--ac)}
#edbar button{flex:1;font-size:14px}
#undo{position:fixed;left:10px;right:10px;bottom:calc(env(safe-area-inset-bottom) + 72px);z-index:12;display:none;
 align-items:center;gap:10px;padding:8px 8px 8px 14px;background:var(--fg);color:var(--bg);border-radius:12px;
 font-weight:700;font-size:14px;box-shadow:0 6px 20px rgba(0,0,0,.35)}
#undo span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#undo button{background:transparent;border:none;color:var(--ac);font-weight:800;font-size:14px}
#toast{position:fixed;left:50%;bottom:90px;transform:translateX(-50%);z-index:30;background:var(--ac);color:#fff;
 font-weight:700;font-size:14px;padding:10px 16px;border-radius:10px;opacity:0;transition:opacity .2s;pointer-events:none}
#toast.on{opacity:1}
#ov{position:fixed;inset:0;z-index:40;display:none;flex-direction:column;gap:10px;
 padding:calc(env(safe-area-inset-top) + 14px) 14px 14px;background:var(--bg)}
#ov textarea{flex:1;width:100%;font:13px/1.4 ui-monospace,Menlo,monospace;background:var(--bar);color:var(--fg);
 border:1px solid var(--ln);border-radius:9px;padding:10px}
